mapper.select:
select

from promotions pr
where pr.id = #{id,jdbcType=BIGINT}

select

from promotions pr
where pr.code = #{code,jdbcType=VARCHAR}

select

from promotions pr
where 1 = 1

  and pr.status = #{status,jdbcType=VARCHAR}


  and pr.promotion_type = #{promotionType,jdbcType=VARCHAR}


  and (pr.code like concat('%', #{search,jdbcType=VARCHAR}, '%')
    or pr.name like concat('%', #{search,jdbcType=VARCHAR}, '%'))


  and pr.brand_id = #{brandId,jdbcType=INTEGER}

order by pr.priority asc, pr.code asc

select distinct pr.id as id, pr.code as code, pr.name as name, pr.promotion_type as promotionType, pr.status as status, pr.priority as priority from promotions pr left join promotion_targets pt on pt.promotion_id = pr.id left join promotion_special_prices psp on psp.promotion_id = pr.id where pr.status in
#{status,jdbcType=VARCHAR}
and (pr.start_date is null or pr.start_date <= #{onDate,jdbcType=DATE}) and (pr.end_date is null or pr.end_date >= #{onDate,jdbcType=DATE})
and ( (#{productId,jdbcType=BIGINT} is not null and pt.product_id = #{productId,jdbcType=BIGINT}) or (#{skuId,jdbcType=BIGINT} is not null and (pt.sku_id = #{skuId,jdbcType=BIGINT} or psp.sku_id = #{skuId,jdbcType=BIGINT})) or (#{categoryId,jdbcType=BIGINT} is not null and pt.category_id = #{categoryId,jdbcType=BIGINT}) )
and pr.brand_id in
#{brandId,jdbcType=INTEGER}
order by pr.priority asc, pr.id asc limit #{limit}

